<?php

declare(strict_types=1);

namespace Bowlingliga\Presentation;

use chillerlan\QRCode\Output\QROutputInterface;
use chillerlan\QRCode\QRCode as QrCodeLibrary;
use chillerlan\QRCode\QROptions;

/**
 * Generates QR codes as embedded SVG, locally without an external service
 * (R36.8).
 *
 * Serves the setup of the two-factor login: the authenticator app scans the
 * otpauth URI (R23.6). The output is markup generated by the library without
 * user input in plain text and can be embedded directly.
 */
final class QrCode
{
    public function svg(string $content): string
    {
        $optionList = new QROptions([
            'outputType'       => QROutputInterface::MARKUP_SVG,
            'outputBase64'     => false,
            'svgAddXmlHeader'  => false,
            'addQuietzone'     => true,
            'drawLightModules' => false,
        ]);

        return (new QrCodeLibrary($optionList))->render($content);
    }

    /**
     * QR code as SVG data URI for an <img> (e.g. in the printed score sheet,
     * which mPDF renders).
     */
    public function svgDataUri(string $content): string
    {
        return 'data:image/svg+xml;base64,' . base64_encode($this->svg($content));
    }
}
